contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address player) public payable {
        bool first = c.hasPlayerWagered(player); if (__ESBMC_reverted()) return;
        bool second = c.hasPlayerWagered(player); if (__ESBMC_reverted()) return;

        assert(first == second && second == c.hasPlayerWagered(player));
    }

    receive() external payable {}
}

