    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(address player) internal {
        bool first;
        try c.hasPlayerWagered(player) returns (bool __r) { first = __r; } catch { return; }
        bool second;
        try c.hasPlayerWagered(player) returns (bool __r) { second = __r; } catch { return; }
        assertTrue(first == second && second == c.hasPlayerWagered(player));
    }

    function testFuzz_run(address player) public {
